def parse_error(flag, msg):
    sys.stderr.write(f"PARSE ERROR: Argument: {flag}\n")
    sys.stderr.write(f"             {msg}\n\n")
    sys.stderr.write(BRIEF_TEMPLATE.format(prog=progname()))
    sys.stderr.write("\n")
    sys.exit(1)

def parse_int_value(s, flag):
    try:
        # Match the stream parser closely: a plain decimal integer only.
        if s.strip() != s or s in ("", "+", "-"):
            raise ValueError
        v = int(s, 10)
        return v
    except Exception:
        parse_error(flag, f"Couldn't read argument value from string '{s}'")

def parse_dims(s):
    parts = s.split()
    if len(parts) < 2:
        parse_error("-d (--dimensions)", f"Couldn't read argument value from string '{s}'")
    try:
        a = int(parts[0], 10); b = int(parts[1], 10)
    except Exception:
        parse_error("-d (--dimensions)", f"Couldn't read argument value from string '{s}'")
    return a,b

def parse_args(argv):
    opt = Options(); i=0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            opt.commands.extend(argv[i+1:]); break
        if a in ("-h", "--help"):
            sys.stdout.write(HELP_TEMPLATE.format(prog=progname()))
            sys.exit(0)
        elif a == "--version":
            sys.stdout.write(f"\n{progname()}  version: 1.2\n\n")
            sys.exit(0)
        elif a in ("-q", "--quiet"):
            opt.quiet=True
        elif a in ("-r", "--noreplay"):
            opt.noreplay=True
        elif a in ("-t", "--timeout"):
            opt.timeout=True
        elif a in ("-o", "--override"):
