def default_dimensions(nplayers):
    # The official environment chooses a random size when none is supplied.
    # Use the same style of small square/even maps.
    if nplayers <= 2:
        s = random.choice([20,24,30,34,40,44,45])
        return s,s
    if nplayers == 3:
        s = random.choice([24,30,33,39])
        return s,s
    if nplayers == 4:
