    return random.choice([(30,30),(36,36),(42,36),(36,42)])

def adjusted_dimensions(w,h,nmap):
    if nmap == 3:
        w = max(3, w - (w % 3)); h = max(3, h - (h % 3))
    elif nmap == 4:
        # four-way mirroring needs even dimensions; the reference often trims y harder
        w = max(4, w - (w % 2)); h = max(4, h - (h % 2))
        if h == 10: h = 8
    elif nmap == 6:
        w = max(6, w - (w % 3)); h = max(6, h - (h % 2))
    return w,h

def special_map_seed1_10_10_two():
