        [6,5,4,5,6,3,3,3,2,2],
        [9,6,4,3,3,4,6,4,2,3],
        [8,5,3,2,3,6,7,4,3,4],
        [5,4,3,3,5,8,8,6,9,7],
        [4,3,3,2,4,6,8,6,11,10],
    ]
    strengths_flat=[90,70,104,126,82,57,108,80,103,120,87,97,160,145,75,55,147,147,175,144,62,73,138,110,75,58,134,101,87,71,78,64,87,77,71,54,90,79,43,43,114,83,68,82,68,80,93,64,40,66,120,103,80,108,57,82,126,104,70,90,144,175,147,147,55,75,145,160,97,87,71,87,101,134,58,75,110,138,73,62,43,43,79,90,54,71,77,87,64,78,66,40,64,93,80,68,82,68,83,114]
    owners=[[0]*10 for _ in range(10)]
    strengths=[strengths_flat[i*10:(i+1)*10] for i in range(10)]
    owners[0][7]=2; owners[5][2]=1
