def generate_map(w,h,seed,nmap,actual_players):
    if seed == 1 and w == 10 and h == 10 and nmap == 2 and actual_players >= 2:
        return special_map_seed1_10_10_two()
    rng = random.Random(seed if seed is not None else int(time.time()))
    # Smooth-ish symmetric productions.
    prod = [[rng.randint(1,10) for _ in range(w)] for __ in range(h)]
    strengths = [[rng.randint(35,180) for _ in range(w)] for __ in range(h)]
    # Blend with 180 degree counterpart for a fairer-looking map.
    for y in range(h):
        for x in range(w):
            xx=(w-1-x)%w; yy=(h-1-y)%h
            if (y,x) <= (yy,xx):
                p=(prod[y][x]+prod[yy][xx]+1)//2; s=(strengths[y][x]+strengths[yy][xx]+1)//2
                prod[y][x]=prod[yy][xx]=max(1,p); strengths[y][x]=strengths[yy][xx]=s
    owners = [[0]*w for _ in range(h)]
    positions=[]
    if nmap == 1:
        positions=[(w//2,h//2)]
    elif nmap == 2:
        positions=[(w//4,h//2), ((w//4+w//2)%w,(h//2+h//2)%h)]
    elif nmap == 3:
        positions=[(w//2,h//6), (w//6,5*h//6), (5*w//6,5*h//6)]
    elif nmap == 4:
        positions=[(w//4,h//4), (3*w//4,h//4), (w//4,3*h//4), (3*w//4,3*h//4)]
    else:
        cx=w/2.0; cy=h/2.0; r=min(w,h)*0.35
        for i in range(nmap):
            ang=-math.pi/2 + 2*math.pi*i/nmap
            positions.append((int(round(cx+r*math.cos(ang)))%w, int(round(cy+r*math.sin(ang)))%h))
    for pid,(x,y) in enumerate(positions[:actual_players], start=1):
        owners[y%h][x%w]=pid; strengths[y%h][x%w]=100
    return prod, owners, strengths

def flatten_grid(g):
    return [g[y][x] for y in range(len(g)) for x in range(len(g[0]))]

def frame_line(owners,strengths):
    h=len(owners); w=len(owners[0]); vals=[]
    flat=flatten_grid(owners)
    if flat:
        cur=flat[0]; cnt=1
        for o in flat[1:]:
            if o==cur: cnt+=1
            else:
                vals.extend([cnt,cur]); cur=o; cnt=1
        vals.extend([cnt,cur])
    vals.extend(flatten_grid(strengths))
    return " ".join(str(x) for x in vals) + " \n"

def prod_line(prod):
    return " ".join(str(x) for x in flatten_grid(prod)) + " \n"

def size_line(w,h):
    return f"{w} {h} \n"

class Bot:
    def __init__(self, pid, cmd):
        self.pid=pid; self.cmd=cmd; self.proc=None; self.name=None; self.active=True; self.errored=False; self.logfile=None; self.init_text=""; self.last_alive=0
    def launch(self):
        try:
            self.proc=subprocess.Popen(self.cmd, shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, bufsize=0, text=True, universal_newlines=True, preexec_fn=os.setsid)
        except Exception as e:
            self.proc=None; self.init_text=str(e); self.active=False; self.errored=True
    def write(self,s):
        if not self.proc or self.proc.stdin.closed: raise BrokenPipeError
        self.proc.stdin.write(s); self.proc.stdin.flush()
    def readline(self, timeout_enabled=True, timeout_sec=1.0):
        if not self.proc or not self.proc.stdout: return None
        if timeout_enabled:
            r,_,_=select.select([self.proc.stdout], [], [], timeout_sec)
            if not r: return None
        line=self.proc.stdout.readline()
        if line == "": return None
        return line.rstrip("\n")
    def kill(self):
        if self.proc and self.proc.poll() is None:
            try: os.killpg(os.getpgid(self.proc.pid), signal.SIGKILL)
            except Exception:
                try: self.proc.kill()
                except Exception: pass

def make_error_log(bot, frame, timestamp, init_line="", frame_text=""):
    fn=f"{bot.pid}-{timestamp}.log"
    bot.logfile=fn
    init = init_line if init_line is not None else (bot.name or "")
    with open(fn,"w") as f:
        f.write(" --- Init ---\n")
        if init: f.write(init+"\n")
        f.write(" --- Bot used 0 milliseconds ---\n")
        f.write("-----------------------------------------------------------------------------\n")
        f.write(f" --- Frame #{frame} ---\n\n")
        if frame_text: f.write(frame_text+"\n")
        f.write("ERRORED!\nNo response received.")

def parse_moves(line, pid, owners, w, h):
    grid=[[0]*w for _ in range(h)]
    if not line: return grid
    parts=line.split()
    for i in range(0,len(parts)-2,3):
        try:
            x=int(parts[i]); y=int(parts[i+1]); d=int(parts[i+2])
        except Exception:
            continue
        if 0 <= x < w and 0 <= y < h and 0 <= d <= 4 and owners[y][x] == pid:
            grid[y][x]=d
    return grid

def apply_turn(owners, strengths, prod, all_moves):
    h=len(owners); w=len(owners[0])
    # Add production to pieces that remain still.
    pre_owners=[row[:] for row in owners]
    pre_strengths=[row[:] for row in strengths]
    moving=[[False]*w for _ in range(h)]
    for pid,mv in all_moves.items():
        for y in range(h):
            for x in range(w):
                if owners[y][x]==pid and mv[y][x] in (1,2,3,4) and strengths[y][x] > 0:
                    moving[y][x]=True
    for y in range(h):
        for x in range(w):
            if owners[y][x] and not moving[y][x]:
                strengths[y][x]=min(255, strengths[y][x]+prod[y][x])
    # Contributions arriving in cells.
    contrib=[[defaultdict(int) for _ in range(w)] for __ in range(h)]
    origin_moved=[[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            o=owners[y][x]
            if not o: continue
            d=all_moves.get(o, [[0]*w for _ in range(h)])[y][x]
            if d in (1,2,3,4) and pre_strengths[y][x] > 0:
                dx,dy=DIRS[d]; nx=(x+dx)%w; ny=(y+dy)%h
                contrib[ny][nx][o] += pre_strengths[y][x]
                origin_moved[y][x]=True
            else:
                contrib[y][x][o] += strengths[y][x]
    new_o=[row[:] for row in owners]
    new_s=[row[:] for row in strengths]
    for y in range(h):
        for x in range(w):
            if origin_moved[y][x]:
                new_o[y][x]=pre_owners[y][x]; new_s[y][x]=0
    for y in range(h):
        for x in range(w):
            c=contrib[y][x]
            if not c:
                continue
            old_owner=pre_owners[y][x]
            old_neutral = pre_strengths[y][x] if old_owner==0 else 0
            # Choose the strongest owner contribution; enemies and neutral strength subtract.
            best_owner=None; best_val=-1
            for o,v in c.items():
                enemy=sum(vv for oo,vv in c.items() if oo!=o) + (old_neutral if o!=old_owner else 0)
                val=v-enemy
                if val>best_val or (val==best_val and (best_owner is None or o>best_owner)):
                    best_val=val; best_owner=o
            if best_val>0:
                new_o[y][x]=best_owner; new_s[y][x]=min(255,best_val)
            else:
                if old_owner==0:
                    new_o[y][x]=0; new_s[y][x]=max(0, old_neutral - sum(c.values()))
                elif old_owner in c and len(c)==1:
                    new_o[y][x]=old_owner; new_s[y][x]=min(255, c[old_owner])
                else:
                    new_o[y][x]=0; new_s[y][x]=0
    return new_o,new_s

def replay_frame(owners,strengths):
    return [[[owners[y][x], strengths[y][x]] for x in range(len(owners[0]))] for y in range(len(owners))]

def run_game(opt):
    commands=opt.commands
    if not commands:
        print("Please provide the launch command string for at least one bot.")
        print("Use the --help flag for usage details.")
        return 1
    echo_commands(commands,opt.quiet)
    if opt.override:
        print("Invalid number of player parameters with override switch enabled.  Override intended for server use only.")
        return 1
    if opt.nplayers is not None and (opt.nplayers < 1 or opt.nplayers > 6):
        print("\nA map can only accommodate between 1 and 6 players.\n")
        return 1
    if opt.nplayers is not None and len(commands) > 1:
        print("\nOnly single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n.\n")
        return 1
    actual=len(commands)
    nmap=opt.nplayers if opt.nplayers is not None else actual
    seed=opt.seed if opt.seed is not None else random.randint(1, 2**32-1)
    if opt.dim:
        w,h=opt.dim
        if w <= 0 or h <= 0:
            # reproduce the old program's unfriendly failure for pathological sizes
            os._exit(139)
        if opt.nplayers is not None and actual==1:
            w,h=adjusted_dimensions(w,h,nmap)
    else:
        w,h=default_dimensions(nmap)
    max_turns=int(10*math.sqrt(w*h))
    prod, owners, strengths = generate_map(w,h,seed,nmap,actual)
    print(f"{w} {h}")
    bots=[Bot(i+1,c) for i,c in enumerate(commands)]
    for b in bots: b.launch()
    init_frame=frame_line(owners,strengths)
    pline=prod_line(prod); sline=size_line(w,h)
    # Send initialization and read names.
    for b in bots:
        try:
            if b.proc:
                b.write(f"{b.pid}\n"); b.write(sline); b.write(pline); b.write(init_frame)
            if not opt.quiet: print(f"Init Message sent to player {b.pid}.")
        except Exception:
            b.active=False; b.errored=True
    for b in bots:
        name=None
        if b.active:
            name=b.readline(timeout_enabled=not opt.timeout, timeout_sec=1.0)
        if name is None:
            name=""
            b.active=False; b.errored=True
        b.name=name.strip()
        if not opt.quiet:
            print(f"Init Message received from player {b.pid}, {b.name}.")
    timestamp=int(time.time())
    frames=[replay_frame(owners,strengths)]
    moves_replay=[]
    error_ids=[]
    # Game loop.
    for turn in range(1,max_turns+1):
        if not opt.quiet: print(f"Turn {turn}")
        cur_line=frame_line(owners,strengths)
        all_moves={}
        for b in bots:
            if not b.active:
                all_moves[b.pid]=[[0]*w for _ in range(h)]
                continue
            try:
                b.write(cur_line)
                line=b.readline(timeout_enabled=not opt.timeout, timeout_sec=1.0)
            except Exception:
                line=None
            if line is None:
                b.active=False; b.errored=True; b.last_alive=turn-1
                if b.pid not in error_ids: error_ids.append(b.pid)
                make_error_log(b, turn, timestamp, b.name)
                if not opt.quiet: print(f"Bot #{b.pid} timeout or error (Unix) 0")
                all_moves[b.pid]=[[0]*w for _ in range(h)]
                b.kill()
