            print(f"Opening a file at {replay_path}")
    # Ranking.
    scores={}
    for b in bots:
        cells=0; total=0
        for y in range(h):
            for x in range(w):
                if owners[y][x]==b.pid:
                    cells+=1; total+=strengths[y][x]
        scores[b.pid]=(cells,total)
    order=sorted([b.pid for b in bots], key=lambda p:(scores[p][0],scores[p][1],p), reverse=True)
    rank={pid:i+1 for i,pid in enumerate(order)}
    if opt.quiet:
        for b in bots:
            print(f"{b.pid} {rank[b.pid]} {b.last_alive}")
        if error_ids: print(" ".join(str(i) for i in error_ids)+" ")
        else: print(" ")
        logs=[b.logfile for b in bots if b.logfile]
        if logs: sys.stdout.write(" ".join(logs)+" ")
        else: sys.stdout.write(" ")
    else:
        for b in bots:
            print(f"Player #{b.pid}, {b.name}, came in rank #{rank[b.pid]} and was last alive on frame #{b.last_alive}!")
    return 0

def main():
    opt=parse_args(sys.argv[1:])
    return run_game(opt)

if __name__ == "__main__":
    sys.exit(main())
